#!/usr/bin/env node
import fs from "node:fs";import os from "node:os";import path from "node:path";import {execFileSync} from "node:child_process";import crypto from "node:crypto";
const dir=fs.mkdtempSync(path.join(os.tmpdir(),"gp10-")),src=path.join(dir,"production.json");fs.copyFileSync("test/fixtures/firestore-phase10.json",src);const before=fs.readFileSync(src,"utf8"),hash=x=>crypto.createHash("sha256").update(x).digest("hex");
const dry=execFileSync(process.execPath,["scripts/rehearse-production-migration.mjs",src],{encoding:"utf8"});if(!dry.includes("Dry-run: bron en Firestore zijn niet gewijzigd."))throw new Error("dry-run contract ontbreekt");if(hash(fs.readFileSync(src,"utf8"))!==hash(before))throw new Error("bron-snapshot gewijzigd");if(fs.existsSync(src.replace(/\.json$/,"-phase10.json")))throw new Error("dry-run schreef target");
execFileSync(process.execPath,["scripts/rehearse-production-migration.mjs",src,"--apply"],{encoding:"utf8"});const out=JSON.parse(fs.readFileSync(src.replace(/\.json$/,"-phase10.json"),"utf8")),rep=JSON.parse(fs.readFileSync(src.replace(/\.json$/,"-phase10-report.json"),"utf8"));
if(rep.checks.blockers.length||!rep.checks.resultCountsMatch||!rep.checks.progressCountsMatch||!rep.checks.sourceUnmodified)throw new Error("repetitie-invarianten niet groen");if(rep.source.results!==2||rep.target.results!==2||rep.source.progress!==1||rep.target.progress!==1)throw new Error("aantallen onverwacht");if(out.memberships.g1.p_owner.role!=="admin"||out.memberships.g1.p_member.status!=="approved")throw new Error("memberships fout");if(out.profiles["auth-owner"].preferences.tutorials.bin!=="skipped")throw new Error("tutorialcompatibiliteit fout");const first=fs.readFileSync(src.replace(/\.json$/,"-phase10.json"),"utf8");execFileSync(process.execPath,["scripts/rehearse-production-migration.mjs",src,"--apply"],{encoding:"utf8"});if(fs.readFileSync(src.replace(/\.json$/,"-phase10.json"),"utf8")!==first)throw new Error("repetitie niet deterministisch");console.log("Fase 10 migratierepetitie: dry-run, hashes, mappings, aggregaten, rollback en idempotentie geslaagd.");
